import{_ as t,o as h,c as i,a2 as a}from"./chunks/framework.mRCPFc5l.js";const l=JSON.parse('{"title":"Project-based Learning","description":"","frontmatter":{},"headers":[],"relativePath":"ideas/project-based.md","filePath":"ideas/project-based.md"}'),o={name:"ideas/project-based.md"};function g(r,n,e,c,m,s){return h(),i("div",null,[...n[0]||(n[0]=[a('<h1 id="project-based-learning" tabindex="-1">Project-based Learning <a class="header-anchor" href="#project-based-learning" aria-label="Permalink to &quot;Project-based Learning&quot;">​</a></h1><p>Trên trang này# Project-based Learning <a href="#project-based-learning">​</a> Learner làm một dự án thật, kéo dài nhiều tuần, có sản phẩm cuối cùng cho người ngoài xem. Kiến thức được học <strong>trong lúc cần dùng nó</strong>, không phải trước đó rồi để dành.</p><h2 id="bai-toan-no-sinh-ra-đe-giai-​" tabindex="-1">Bài toán nó sinh ra để giải <a href="#bai-toan-no-sinh-ra-đe-giai">​</a> <a class="header-anchor" href="#bai-toan-no-sinh-ra-đe-giai-​" aria-label="Permalink to &quot;Bài toán nó sinh ra để giải [​](#bai-toan-no-sinh-ra-đe-giai)&quot;">​</a></h2><p>Học sinh học xong một chương và không biết nó dùng để làm gì. Câu hỏi &quot;học cái này để làm gì ạ&quot; không có câu trả lời thật, và động lực rơi xuống. Project-based đảo ngược trình tự: đặt một vấn đề thật lên trước, và kiến thức trở thành thứ cần thiết để giải nó.</p><h2 id="mot-du-an-đung-nghia-gom-gi-​" tabindex="-1">Một dự án đúng nghĩa gồm gì <a href="#mot-du-an-đung-nghia-gom-gi">​</a> <a class="header-anchor" href="#mot-du-an-đung-nghia-gom-gi-​" aria-label="Permalink to &quot;Một dự án đúng nghĩa gồm gì [​](#mot-du-an-đung-nghia-gom-gi)&quot;">​</a></h2><p>Thành phầnNghĩa làCâu hỏi mởKhông có sẵn đáp án đúng để traSản phẩm thậtCó người ngoài lớp xem, dùng, hoặc phản hồiKéo dàiVài tuần, không phải một tiếtLearner tự quyếtÍt nhất một số quyết định là của learnerSửa nhiều vòngNộp bản nháp, nhận góp ý, làm lạiTrình bày công khaiNói được về thứ mình làmThiếu &quot;sửa nhiều vòng&quot; và &quot;sản phẩm thật&quot;, cái gọi là dự án thường chỉ là một bài tập lớn được gọi tên khác.</p><h2 id="manh-o-đau-​" tabindex="-1">Mạnh ở đâu <a href="#manh-o-đau">​</a> <a class="header-anchor" href="#manh-o-đau-​" aria-label="Permalink to &quot;Mạnh ở đâu [​](#manh-o-đau)&quot;">​</a></h2><p><strong>Động lực.</strong> Đây là điểm mạnh rõ nhất. Làm một thứ có người xem tạo ra loại nỗ lực mà bài tập về nhà không tạo ra được. <strong>Tích hợp.</strong> Một dự án thật hiếm khi nằm gọn trong một môn. Làm một video về ô nhiễm nước cần sinh học, hoá học, thống kê, viết kịch bản, quay dựng. <strong>Kỹ năng không có trong bảng điểm.</strong> Chia việc, giữ hạn, xử lý bất đồng trong nhóm, trình bày trước người lạ — không môn nào dạy những thứ này, và chúng quan trọng suốt đời. <strong>Nhớ lâu hơn.</strong> Kiến thức dùng để giải một vấn đề thật bám tốt hơn kiến thức học để trả bài.</p><h2 id="yeu-o-đau-​" tabindex="-1">Yếu ở đâu <a href="#yeu-o-đau">​</a> <a class="header-anchor" href="#yeu-o-đau-​" aria-label="Permalink to &quot;Yếu ở đâu [​](#yeu-o-đau)&quot;">​</a></h2><p><strong>Không đảm bảo phủ đủ.</strong> Một dự án hay có thể chỉ chạm tới ba trong mười kiến thức cần học. Những phần còn lại không tự xuất hiện. <strong>Người có nền yếu bị chìm.</strong> Trong nhóm, học sinh yếu thường nhận phần việc dễ — dán ảnh, làm slide — và học được ít nhất, trong khi kết quả nhóm vẫn tốt và che mất điều đó. <strong>Khó đo từng cá nhân.</strong> Ai đã thật sự làm gì? Điểm nhóm giấu đi rất nhiều. <strong>Rất tốn thời gian.</strong> Ba tuần cho một dự án chạm ba khái niệm là cái giá không phải lúc nào cũng trả nổi. <strong>Dễ thành hoạt động vui mà rỗng.</strong> Cả lớp bận rộn, sản phẩm đẹp, không ai học được gì mới. Đây là thất bại phổ biến nhất — và khó phát hiện, vì nhìn từ ngoài mọi thứ đều rất tích cực.</p><h2 id="đieu-kien-đe-no-hoat-đong-​" tabindex="-1">Điều kiện để nó hoạt động <a href="#đieu-kien-đe-no-hoat-đong">​</a> <a class="header-anchor" href="#đieu-kien-đe-no-hoat-đong-​" aria-label="Permalink to &quot;Điều kiện để nó hoạt động [​](#đieu-kien-đe-no-hoat-đong)&quot;">​</a></h2><p><strong>Phải có nền trước.</strong> Dự án là nơi <em>dùng</em> kiến thức, không phải nơi học kiến thức từ số không. Học sinh chưa biết gì về thống kê sẽ không học được thống kê qua một dự án khảo sát — em ấy sẽ đi nhờ người khác làm phần đó. <strong>Phải nêu rõ học gì.</strong> Trước khi bắt đầu: dự án này nhằm rèn ba kỹ năng cụ thể nào? Không có câu trả lời rõ ràng thì thường là không có gì được rèn. <strong>Phải đo cá nhân.</strong> Nhật ký làm việc, phần đóng góp ghi rõ, hoặc một bài kiểm tra riêng sau dự án. <strong>Phải có nhiều vòng góp ý.</strong> Nộp một lần rồi chấm không phải project-based — đó là bài tập lớn.</p><h2 id="nemo12-dung-no-the-nao-​" tabindex="-1">Nemo12 dùng nó thế nào <a href="#nemo12-dung-no-the-nao">​</a> <a class="header-anchor" href="#nemo12-dung-no-the-nao-​" aria-label="Permalink to &quot;Nemo12 dùng nó thế nào [​](#nemo12-dung-no-the-nao)&quot;">​</a></h2><p>Nemo12 tập trung vào việc xây nền vững, nên project-based không phải khung chính của hệ thống. Nhưng nó xuất hiện ở hai chỗ: <strong>Trong Student Portrait.</strong> Milestone kiểu &quot;hoàn thành một dự án tự chọn từ đầu tới cuối&quot; là milestone có giá trị cao — và nó thường được làm ngoài hệ thống, ở nhà hoặc ở trường. Nemo12 ghi nhận nó như một phần thật của bức tranh. <a href="/portrait/milestone">Xem milestone →</a><strong>Ở tầng sâu nhất của việc học.</strong> Bậc cao nhất trong thang độ sâu là dùng được kiến thức trong tình huống lạ và nối được nó với các mảng khác. Đây chính là thứ mà một dự án tốt đòi hỏi. <a href="/learning/hoc-ky">Xem sáu bậc sâu →</a> Ở nhà Dự án gia đình không cần hoành tráng. &quot;Tính xem một tháng nhà mình tốn bao nhiêu tiền điện cho mỗi thiết bị, rồi đề xuất cách giảm&quot; là một dự án tốt: có số liệu thật, có toán thật, có kết luận dùng được, và có người xem — cả nhà. Dự án là nơi kiến thức được dùng, không phải nơi kiến thức được xây. Nhầm hai vai trò này là lý do nhiều dự án trông rất đẹp nhưng không dạy được gì. <a href="/ideas/montessori-reggio-classical">Montessori · Reggio Emilia · Classical →</a></p>',14)])])}const d=t(o,[["render",g]]);export{l as __pageData,d as default};
